public enum AccountType {
    CHECKING(0), SAVINGS(500);   // overdraft limit in cents
    private final long overdraftLimit;
    AccountType(long overdraftLimit) {
        this.overdraftLimit = overdraftLimit;
    }

    public long overdraftLimit() {
        return overdraftLimit;
    }
}

package com.example.bank.model;

import java.time.LocalDate;

public record Transaction(LocalDate date, String kind, long amountCents, long balanceAfter) {
    public Transaction {
        if (kind == null || kind.isBlank()) {
            throw new IllegalArgumentException("kind required");
        }
    }

    @Override
    public String toString() {
        return "%s %-12s %10s  balance %10s".formatted(
                date, kind, Money.format(amountCents), Money.format(balanceAfter));
    }
}

package com.example.bank.model;

public final class Money {
    private Money() { }

    /** Parses "12.34" or "12" into cents. */
    public static long parse(String text) {
        String t = text.trim();
        int dot = t.indexOf('.');
        try {
            if (dot < 0) {
                return Math.multiplyExact(Long.parseLong(t), 100L);
            }
            String frac = t.substring(dot + 1);
            if (frac.length() != 2) {
                throw new NumberFormatException("need exactly 2 decimals");
            }
            long whole = Long.parseLong(t.substring(0, dot));
            return Math.addExact(Math.multiplyExact(whole, 100L), Long.parseLong(frac));
        } catch (NumberFormatException | ArithmeticException e) {
            throw new InvalidAmountException("bad amount: '" + text + "'", e);
        }
    }

    public static String format(long cents) {
        String sign = cents < 0 ? "-" : "";
        long abs = Math.abs(cents);
        return "%s%d.%02d".formatted(sign, abs / 100, abs % 100);
    }
}

package com.example.bank.model;

/** Checked: callers must decide what to do when the money is not there. */
public class InsufficientFundsException extends Exception {
    private final long shortfallCents;

    public InsufficientFundsException(String accountId, long shortfallCents) {
        super("account " + accountId + " is short by " + Money.format(shortfallCents));
        this.shortfallCents = shortfallCents;
    }

    public long shortfallCents() {
        return shortfallCents;
    }
}

package com.example.bank.model;

/** Unchecked: a programming or input error, not a business outcome. */
public class InvalidAmountException extends IllegalArgumentException {
    public InvalidAmountException(String message) {
        super(message);
    }

    public InvalidAmountException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.example.bank.model;

import java.time.Clock;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

public class Account {
    private final String id;
    private final String owner;
    private final AccountType type;
    private long balanceCents;
    private final List<Transaction> history = new ArrayList<>();

    public Account(String id, String owner, AccountType type, long openingCents) {
        this.id = Objects.requireNonNull(id);
        this.owner = Objects.requireNonNull(owner);
        this.type = Objects.requireNonNull(type);
        if (openingCents < 0) {
            throw new InvalidAmountException("opening balance must not be negative");
        }
        this.balanceCents = openingCents;
    }

    public String id() { return id; }
    public String owner() { return owner; }
    public AccountType type() { return type; }
    public long balanceCents() { return balanceCents; }

    /** Read-only view: callers cannot modify our history. */
    public List<Transaction> history() {
        return Collections.unmodifiableList(history);
    }

    public void deposit(long cents, Clock clock) {
        requirePositive(cents);
        balanceCents = Math.addExact(balanceCents, cents);
        history.add(new Transaction(LocalDate.now(clock), "DEPOSIT", cents, balanceCents));
    }

    public void withdraw(long cents, Clock clock) throws InsufficientFundsException {
        requirePositive(cents);
        long available = balanceCents + type.overdraftLimit();
        if (cents > available) {
            throw new InsufficientFundsException(id, cents - available);
        }
        balanceCents -= cents;
        history.add(new Transaction(LocalDate.now(clock), "WITHDRAW", cents, balanceCents));
    }

    private static void requirePositive(long cents) {
        if (cents <= 0) {
            throw new InvalidAmountException("amount must be positive, got " + Money.format(cents));
        }
    }

    /** Used by the repository when loading from disk (history is not persisted). */
    public static Account restore(String id, String owner, AccountType type, long cents) {
        return new Account(id, owner, type, Math.max(cents, 0)).withBalance(cents);
    }

    private Account withBalance(long cents) {
        this.balanceCents = cents;
        return this;
    }

    @Override
    public String toString() {
        return "%s [%s] %s %s".formatted(id, type, owner, Money.format(balanceCents));
    }
}

package com.example.bank.repo;
import java.util.List;
