public interface Repository<T, ID> {
    Optional<T> findById(ID id);
    List<T> findAll();
    void save(T entity);
}

package com.example.bank.repo;

import com.example.bank.model.Account;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
public class InMemoryAccountRepository implements Repository<Account, String> {
    private final Map<String, Account> accounts = new TreeMap<>();   // sorted by id

    @Override
    public Optional<Account> findById(String id) {
        return Optional.ofNullable(accounts.get(id));
    }

    @Override
    public List<Account> findAll() {
        return new ArrayList<>(accounts.values());
    }

    @Override
    public void save(Account account) {
        accounts.put(account.id(), account);
    }
}

package com.example.bank.repo;

import com.example.bank.model.Account;
import com.example.bank.model.AccountType;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

/** Wraps another repository and persists all accounts to a CSV file after every save. */
public class FileAccountRepository implements Repository<Account, String> {
    private final Path file;
    private final InMemoryAccountRepository cache = new InMemoryAccountRepository();

    public FileAccountRepository(Path file) {
        this.file = file;
        load();
    }

    private void load() {
        if (!Files.exists(file)) {
            return;
        }
        try {
            for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                if (line.isBlank() || line.startsWith("#")) {
                    continue;
                }
                String[] p = line.split(",", -1);
                cache.save(Account.restore(p[0], p[1], AccountType.valueOf(p[2]),
                        Long.parseLong(p[3])));
            }
        } catch (IOException e) {
            throw new UncheckedIOException("cannot read " + file, e);
        }
    }

    @Override
    public Optional<Account> findById(String id) {
        return cache.findById(id);
    }

    @Override
    public List<Account> findAll() {
        return cache.findAll();
    }
    @Override
    public void save(Account account) {
        cache.save(account);
        flush();
    }

    /** Write to a temp file, then move it over the real one: a crash cannot leave half a file. */
    private void flush() {
        List<String> lines = new ArrayList<>();
        lines.add("# id,owner,type,balanceCents");
        for (Account a : cache.findAll()) {
            lines.add(String.join(",", a.id(), a.owner(), a.type().name(),
                    Long.toString(a.balanceCents())));
        }
        try {
            Path tmp = file.resolveSibling(file.getFileName() + ".tmp");
            Files.write(tmp, lines, StandardCharsets.UTF_8);
            Files.move(tmp, file, StandardCopyOption.REPLACE_EXISTING,
                    StandardCopyOption.ATOMIC_MOVE);
        } catch (IOException e) {
            throw new UncheckedIOException("cannot write " + file, e);
        }
    }
}

package com.example.bank.service;

import com.example.bank.model.Account;
import com.example.bank.model.AccountType;
import com.example.bank.model.InsufficientFundsException;
import com.example.bank.model.InvalidAmountException;
import com.example.bank.repo.Repository;
import java.time.Clock;
import java.util.List;
import java.util.NoSuchElementException;

public class BankService {
    private final Repository<Account, String> repo;
    private final Clock clock;
    private int nextNumber;

    public BankService(Repository<Account, String> repo, Clock clock) {
        this.repo = repo;
        this.clock = clock;
        this.nextNumber = repo.findAll().size() + 1;
    }

    public Account open(String owner, AccountType type, long openingCents) {
        Account a = new Account("AC%03d".formatted(nextNumber++), owner, type, openingCents);
        repo.save(a);
        return a;
    }

    public Account get(String id) {
        return repo.findById(id).orElseThrow(() -> new NoSuchElementException("no account " + id));
    }

    public List<Account> all() {
        return repo.findAll();
    }

    public void deposit(String id, long cents) {
        Account a = get(id);
        a.deposit(cents, clock);
        repo.save(a);
    }

    public void withdraw(String id, long cents) throws InsufficientFundsException {
        Account a = get(id);
        a.withdraw(cents, clock);
        repo.save(a);
    }

    /** Both legs succeed or neither does: withdraw first (it can fail), then deposit. */
    public void transfer(String from, String to, long cents) throws InsufficientFundsException {
        if (from.equals(to)) {
            throw new InvalidAmountException("cannot transfer to the same account");
        }
        Account src = get(from);
        Account dst = get(to);          // look up both BEFORE changing anything
        src.withdraw(cents, clock);
        dst.deposit(cents, clock);
        repo.save(src);
        repo.save(dst);
    }
}

package com.example.bank.app;

import com.example.bank.model.AccountType;
import com.example.bank.model.InsufficientFundsException;
import com.example.bank.model.Money;
import com.example.bank.repo.FileAccountRepository;
import com.example.bank.service.BankService;
import java.io.InputStream;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Scanner;

public class Main {
    private final BankService bank;
    private final Scanner in;

    public Main(BankService bank, InputStream input) {
        this.bank = bank;
        this.in = new Scanner(input);
    }

    public void run() {
        while (in.hasNextLine()) {
            String line = in.nextLine().trim();
            if (line.isEmpty()) {
                continue;
            }
            System.out.println("> " + line);          // echo, since input is scripted
            String[] w = line.split("\\s+");
            try {
                if (!dispatch(w)) {
                    return;
                }
            } catch (InsufficientFundsException e) {
                System.out.println("DECLINED: " + e.getMessage());
            } catch (IllegalArgumentException | java.util.NoSuchElementException e) {
                System.out.println("ERROR: " + e.getMessage());
            }
        }
    }

    /** Returns false when the user asked to quit. */
    private boolean dispatch(String[] w) throws InsufficientFundsException {
        switch (w[0]) {
            case "open" -> {
                var a = bank.open(w[1], AccountType.valueOf(w[2].toUpperCase()), Money.parse(w[3]));
                System.out.println("opened " + a);
            }
            case "deposit" -> bank.deposit(w[1], Money.parse(w[2]));
            case "withdraw" -> bank.withdraw(w[1], Money.parse(w[2]));
            case "transfer" -> bank.transfer(w[1], w[2], Money.parse(w[3]));
            case "list" -> bank.all().forEach(a -> System.out.println("  " + a));
            case "history" -> bank.get(w[1]).history().forEach(t -> System.out.println("  " + t));
            case "quit" -> {
                return false;
            }
            default -> System.out.println("unknown command: " + w[0]);
        }
        return true;
    }

    public static void main(String[] args) {
        Path file = Path.of(args.length > 0 ? args[0] : "accounts.csv");
        Clock clock = Clock.fixed(Instant.parse("2026-03-01T10:00:00Z"), ZoneOffset.UTC);
        new Main(new BankService(new FileAccountRepository(file), clock), System.in).run();
    }
}

package com.example.bank;

import java.util.ArrayList;
import java.util.List;

/** A tiny stand-in for JUnit: register named checks, run them, report, exit non-zero. */
public final class MiniTest {
    public interface Body {
        void run() throws Exception;
    }

    private record Case(String name, Body body) { }

    private final List<Case> cases = new ArrayList<>();

    public void test(String name, Body body) {
        cases.add(new Case(name, body));
    }
    public static void assertEquals(Object expected, Object actual) {
        if (!java.util.Objects.equals(expected, actual)) {
            throw new AssertionError("expected <" + expected + "> but was <" + actual + ">");
        }
    }

    public static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    public static <T extends Throwable> void assertThrows(Class<T> type, Body body) {
        try {
            body.run();
        } catch (Throwable t) {
            if (type.isInstance(t)) {
                return;
            }
            throw new AssertionError("expected " + type.getSimpleName() + " but got " + t);
        }
        throw new AssertionError("expected " + type.getSimpleName() + " but nothing was thrown");
    }

    public int runAll() {
        int failed = 0;
        for (Case c : cases) {
            try {
                c.body().run();
                System.out.println("PASS " + c.name());
            } catch (Throwable t) {
                failed++;
                System.out.println("FAIL " + c.name() + " -> " + t.getMessage());
            }
        }
        System.out.printf("%d tests, %d failed%n", cases.size(), failed);
        return failed;
    }
}

package com.example.bank;

import static com.example.bank.MiniTest.assertEquals;
import static com.example.bank.MiniTest.assertThrows;

import com.example.bank.model.AccountType;
import com.example.bank.model.InsufficientFundsException;
import com.example.bank.model.InvalidAmountException;
import com.example.bank.model.Money;
import com.example.bank.repo.FileAccountRepository;
import com.example.bank.repo.InMemoryAccountRepository;
import com.example.bank.service.BankService;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;

public class BankTests {
    static final Clock CLOCK = Clock.fixed(Instant.parse("2026-03-01T00:00:00Z"), ZoneOffset.UTC);

    static BankService newBank() {
        return new BankService(new InMemoryAccountRepository(), CLOCK);
    }

    public static void main(String[] args) {
        MiniTest t = new MiniTest();

        t.test("Money.parse handles whole and fractional amounts", () -> {
            assertEquals(1250L, Money.parse("12.50"));
            assertEquals(700L, Money.parse("7"));
        });
        t.test("Money.parse rejects one-decimal input", () ->
                assertThrows(InvalidAmountException.class, () -> Money.parse("1.5")));
        t.test("Money.format round-trips negatives", () ->
                assertEquals("-0.05", Money.format(-5)));
        t.test("deposit increases balance and records history", () -> {
            var bank = newBank();
            var a = bank.open("Asha", AccountType.CHECKING, 1000);
            bank.deposit(a.id(), 250);
            assertEquals(1250L, bank.get(a.id()).balanceCents());
            assertEquals(1, bank.get(a.id()).history().size());
        });
        t.test("withdraw beyond balance throws checked exception", () -> {
            var bank = newBank();
            var a = bank.open("Asha", AccountType.CHECKING, 1000);
            assertThrows(InsufficientFundsException.class, () -> bank.withdraw(a.id(), 1001));
            assertEquals(1000L, bank.get(a.id()).balanceCents());
        });
        t.test("savings may overdraw up to the limit", () -> {
            var bank = newBank();
            var a = bank.open("Ravi", AccountType.SAVINGS, 1000);
            bank.withdraw(a.id(), 1500);
            assertEquals(-500L, bank.get(a.id()).balanceCents());
        });
        t.test("failed transfer changes neither account", () -> {
            var bank = newBank();
            var a = bank.open("A", AccountType.CHECKING, 1000);
            var b = bank.open("B", AccountType.CHECKING, 0);
            assertThrows(InsufficientFundsException.class,
                    () -> bank.transfer(a.id(), b.id(), 5000));
            assertEquals(1000L, bank.get(a.id()).balanceCents());
            assertEquals(0L, bank.get(b.id()).balanceCents());
        });
        t.test("history view cannot be modified", () -> {
            var a = newBank().open("A", AccountType.CHECKING, 0);
            assertThrows(UnsupportedOperationException.class, () -> a.history().clear());
        });
        t.test("file repository survives a restart", () -> {
            Path f = Files.createTempFile("accounts", ".csv");
            var bank = new BankService(new FileAccountRepository(f), CLOCK);
            var a = bank.open("Asha", AccountType.CHECKING, 4200);
            var reloaded = new BankService(new FileAccountRepository(f), CLOCK);
            assertEquals(4200L, reloaded.get(a.id()).balanceCents());
            Files.delete(f);
        });

        System.exit(t.runAll() == 0 ? 0 : 1);
    }
}

package com.example.logs.model;

public enum Level {
    DEBUG, INFO, WARN, ERROR;

    public boolean atLeast(Level other) {
        return compareTo(other) >= 0;
    }
}

package com.example.logs.model;
import java.time.Instant;
public record LogEntry(Instant time, Level level, String service, String method,
                       String path, int status, int millis, String user) {
    /** "/orders/42" and "/orders/77" are the same endpoint: collapse numeric ids. */
    public String endpoint() {
        return method + " " + path.replaceAll("/\\d+", "/{id}");
    }

    public boolean isServerError() {
        return status >= 500;
    }
}

package com.example.logs.io;

import com.example.logs.model.Level;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/** Writes a reproducible fake log: the same seed always gives the same file. */
public final class LogGenerator {
    private static final String[] SERVICES = {"api", "auth", "billing"};
    private static final String[] PATHS = {"/orders", "/orders/%d", "/login", "/users/%d",
        "/invoices/%d", "/health"};
    private static final String[] METHODS = {"GET", "GET", "GET", "POST", "PUT"};

    private LogGenerator() { }

    public static void write(Path file, int lines, long seed, Instant start) {
        Random rnd = new Random(seed);
        List<String> out = new ArrayList<>(lines);
        Instant t = start;
        for (int i = 0; i < lines; i++) {
            t = t.plusMillis(1 + rnd.nextInt(15_000));          // up to 15 s between lines
            if (i % 97 == 96) {
                out.add("### corrupted line " + i);              // malformed on purpose
                continue;
            }
            int status = pickStatus(rnd);
            Level level = status >= 500 ? Level.ERROR : status >= 400 ? Level.WARN
                    : rnd.nextInt(10) == 0 ? Level.DEBUG : Level.INFO;
            String service = SERVICES[rnd.nextInt(SERVICES.length)];
            String path = PATHS[rnd.nextInt(PATHS.length)].formatted(1 + rnd.nextInt(500));
            int millis = 5 + (int) (-Math.log(1 - rnd.nextDouble()) * 40)
                    + (status >= 500 ? 300 : 0);
            out.add("%s %-5s [%s] %s %s %d %dms user=u%02d".formatted(t, level, service,
                    METHODS[rnd.nextInt(METHODS.length)], path, status, millis, rnd.nextInt(40)));
        }
        try {
            Files.write(file, out);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    private static int pickStatus(Random rnd) {
        int r = rnd.nextInt(100);
        if (r < 85) {
            return 200;
        } else if (r < 90) {
            return 201;
        } else if (r < 95) {
            return 404;
        } else if (r < 97) {
            return 401;
        }
        return 500;
    }
}

package com.example.logs.io;

import com.example.logs.model.Level;
import com.example.logs.model.LogEntry;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public final class LogParser {
    // named groups make the pattern self-documenting
    private static final Pattern LINE = Pattern.compile(
            "^(?<ts>\\S+)\\s+(?<level>[A-Z]+)\\s+\\[(?<svc>[a-z]+)]\\s+"
            + "(?<method>[A-Z]+)\\s+(?<path>\\S+)\\s+(?<status>\\d{3})\\s+"
            + "(?<ms>\\d+)ms\\s+user=(?<user>\\w+)$");

    private LogParser() { }

    /** Empty means "this line is not a valid entry"; the caller counts it. */
    public static Optional<LogEntry> parse(String line) {
        Matcher m = LINE.matcher(line);
        if (!m.matches()) {
            return Optional.empty();
        }
        try {
            return Optional.of(new LogEntry(
                    Instant.parse(m.group("ts")),
                    Level.valueOf(m.group("level")),
                    m.group("svc"),
                    m.group("method"),
                    m.group("path"),
                    Integer.parseInt(m.group("status")),
                    Integer.parseInt(m.group("ms")),
                    m.group("user")));
        } catch (DateTimeParseException | IllegalArgumentException e) {
            return Optional.empty();
        }
    }
}

