import com.example.logs.model.LogEntry;
import java.time.Instant;
import java.util.List;
import java.util.Map;

/** Everything the analyzer computed; plain data so tests can inspect each piece. */
public record Report(int total, int malformed, Instant first, Instant last,
                     Map<Level, Long> byLevel,
                     List<Map.Entry<String, Long>> topEndpoints,
                     Map<String, Double> avgMillisByService,
                     long p95Millis,
                     Map<Instant, Long> errorsPerHour,
                     Map<Boolean, Long> okVsFailed,
                     List<LogEntry> slowest) { }

package com.example.logs.analysis;

import com.example.logs.io.LogParser;
import com.example.logs.model.Level;
import com.example.logs.model.LogEntry;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.temporal.ChronoUnit;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public final class Analyzer {
    private Analyzer() { }

    public static Report analyze(Path file) {
        try (Stream<String> lines = Files.lines(file)) {
            List<String> all = lines.filter(l -> !l.isBlank()).toList();
            List<LogEntry> entries = all.stream()
                    .map(LogParser::parse)
                    .flatMap(Optional::stream)          // drops the empty Optionals
                    .toList();
            return analyze(entries, all.size() - entries.size());
        } catch (IOException e) {
            throw new UncheckedIOException("cannot read " + file, e);
        }
    }

    public static Report analyze(List<LogEntry> entries, int malformed) {
        Map<Level, Long> byLevel = entries.stream().collect(Collectors.groupingBy(
                LogEntry::level, () -> new TreeMap<>(), Collectors.counting()));

        List<Map.Entry<String, Long>> top = entries.stream()
                .collect(Collectors.groupingBy(LogEntry::endpoint, Collectors.counting()))
                .entrySet().stream()
                .sorted(Map.Entry.<String, Long>comparingByValue().reversed()
                        .thenComparing(Map.Entry.comparingByKey()))
                .limit(5)
                .toList();

        Map<String, Double> avg = entries.stream().collect(Collectors.groupingBy(
                LogEntry::service, TreeMap::new, Collectors.averagingInt(LogEntry::millis)));

        long[] sorted = entries.stream().mapToLong(LogEntry::millis).sorted().toArray();
        long p95 = sorted.length == 0 ? 0 : sorted[(int) Math.ceil(sorted.length * 0.95) - 1];

        Map<java.time.Instant, Long> errorsPerHour = entries.stream()
                .filter(e -> e.level() == Level.ERROR)
                .collect(Collectors.groupingBy(e -> e.time().truncatedTo(ChronoUnit.HOURS),
                        TreeMap::new, Collectors.counting()));

        Map<Boolean, Long> okVsFailed = entries.stream()
                .collect(Collectors.partitioningBy(e -> e.status() < 400, Collectors.counting()));

        List<LogEntry> slowest = entries.stream()
                .sorted(Comparator.comparingInt(LogEntry::millis).reversed()
                        .thenComparing(LogEntry::time))
                .limit(3)
                .toList();

        return new Report(entries.size(), malformed,
                entries.stream().map(LogEntry::time).min(Comparator.naturalOrder()).orElse(null),
                entries.stream().map(LogEntry::time).max(Comparator.naturalOrder()).orElse(null),
                byLevel, top, avg, p95, errorsPerHour, okVsFailed, slowest);
    }
}

