package com.example.orders.model;

import java.util.Collection;

/** Order-independent digest of a run: two correct runs must produce equal summaries. */
public record Summary(int accepted, int rejected, long checksum) {
    public static Summary of(Collection<Result> results) {
        int ok = 0;
        int bad = 0;
        long sum = 0;
        for (Result r : results) {
            if (r.status() == Result.Status.ACCEPTED) {
                ok++;
            } else {
                bad++;
            }
            sum += r.orderId() * (r.status() == Result.Status.ACCEPTED ? 1L : 2L);
        }
        return new Summary(ok, bad, sum);
    }
}

