package com.example.orders.work;

import com.example.orders.model.Order;
import com.example.orders.model.Result;

/** The "business logic": pretend to call a payment service (a blocking wait), then decide. */
public final class OrderProcessor {
    private final long latencyMillis;

    public OrderProcessor(long latencyMillis) {
        this.latencyMillis = latencyMillis;
    }

    public Result process(Order o) {
        try {
            Thread.sleep(latencyMillis);                  // stands in for network I/O
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();           // restore the flag, then bail out
            throw new IllegalStateException("interrupted while processing " + o.id(), e);
        }
        if (o.amountCents() > 90_000) {
            return Result.rejected(o, "over limit");
        }
        if (o.customer().endsWith("13")) {
            return Result.rejected(o, "blocked customer");
        }
        return Result.accepted(o);
    }
}

