package com.example.orders.run;

import com.example.orders.model.Order;
import com.example.orders.model.Result;
import com.example.orders.work.OrderProcessor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ArrayBlockingQueue;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.ConcurrentLinkedQueue;

/** Classic producer-consumer: one producer thread, N consumer threads, a bounded queue. */
public class QueueRunner implements Runner {
    private static final Order POISON = new Order(-1, "poison", 0);

    private final OrderProcessor processor;
    private final int consumers;
    private final int capacity;

    public QueueRunner(OrderProcessor processor, int consumers, int capacity) {
        this.processor = processor;
        this.consumers = consumers;
        this.capacity = capacity;
    }

    @Override
    public String name() {
        return "queue(" + consumers + " consumers)";
    }

    @Override
    public List<Result> run(List<Order> orders) throws InterruptedException {
        BlockingQueue<Order> queue = new ArrayBlockingQueue<>(capacity);
        ConcurrentLinkedQueue<Result> results = new ConcurrentLinkedQueue<>();

        Thread producer = new Thread(() -> {
            try {
                for (Order o : orders) {
                    queue.put(o);                    // blocks when the queue is full: back-pressure
                }
                for (int i = 0; i < consumers; i++) {
                    queue.put(POISON);               // one pill per consumer
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }, "producer");

        List<Thread> workers = new ArrayList<>();
        for (int i = 0; i < consumers; i++) {
            Thread w = new Thread(() -> {
                try {
                    while (true) {
                        Order o = queue.take();      // blocks when the queue is empty
                        if (o == POISON) {
                            return;
                        }
                        results.add(processor.process(o));
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }, "consumer-" + i);
            workers.add(w);
        }

        producer.start();
        workers.forEach(Thread::start);
        producer.join();
        for (Thread w : workers) {
            w.join();
        }
        return new ArrayList<>(results);
    }
}

package com.example.orders.run;

import com.example.orders.model.Order;
import com.example.orders.model.Result;
import com.example.orders.work.OrderProcessor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

/** A fixed thread pool; invokeAll submits everything and waits for all the futures. */
public class PoolRunner implements Runner {
    private final OrderProcessor processor;
    private final int threads;

    public PoolRunner(OrderProcessor processor, int threads) {
        this.processor = processor;
        this.threads = threads;
    }

    @Override
    public String name() {
        return "pool(" + threads + " threads)";
    }

    @Override
    public List<Result> run(List<Order> orders) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        try {
            List<Callable<Result>> tasks = new ArrayList<>();
            for (Order o : orders) {
                tasks.add(() -> processor.process(o));
            }
            List<Result> results = new ArrayList<>();
            for (Future<Result> f : pool.invokeAll(tasks)) {
                results.add(f.get());                // rethrows task failures as ExecutionException
            }
            return results;
        } finally {
            shutdownGracefully(pool);
        }
    }

    /** Stop accepting work, wait a while, then interrupt whatever is still running. */
    static void shutdownGracefully(ExecutorService pool) throws InterruptedException {
        pool.shutdown();
        if (!pool.awaitTermination(5, TimeUnit.SECONDS)) {
            pool.shutdownNow();
            pool.awaitTermination(5, TimeUnit.SECONDS);
        }
    }
}

package com.example.orders.run;

import com.example.orders.model.Order;
import com.example.orders.model.Result;
import com.example.orders.work.OrderProcessor;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** One CompletableFuture per order; failures become REJECTED results instead of lost tasks. */
public class FutureRunner implements Runner {
    private final OrderProcessor processor;
    private final int threads;

    public FutureRunner(OrderProcessor processor, int threads) {
        this.processor = processor;
        this.threads = threads;
    }

    @Override
    public String name() {
        return "completable(" + threads + " threads)";
    }

    @Override
    public List<Result> run(List<Order> orders) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        try {
            List<CompletableFuture<Result>> futures = orders.stream()
                    .map(o -> CompletableFuture
                            .supplyAsync(() -> validate(o), pool)
                            .thenApplyAsync(processor::process, pool)
                            .exceptionally(ex -> Result.rejected(o, "failed: " + ex.getMessage())))
                    .toList();
            CompletableFuture.allOf(futures.toArray(CompletableFuture[]::new)).join();
            return futures.stream().map(CompletableFuture::join).toList();
        } finally {
            PoolRunner.shutdownGracefully(pool);
        }
    }

    private static Order validate(Order o) {
        if (o.amountCents() <= 0) {
            throw new IllegalArgumentException("non-positive amount");
        }
        return o;
    }
}

package com.example.orders.run;

import com.example.orders.model.Order;
import com.example.orders.model.Result;
import com.example.orders.work.OrderProcessor;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

/** Java 21: one cheap virtual thread per order, no pool size to tune. */
public class VirtualRunner implements Runner {
    private final OrderProcessor processor;

    public VirtualRunner(OrderProcessor processor) {
        this.processor = processor;
    }

    @Override
    public String name() {
        return "virtual threads";
    }

    @Override
    public List<Result> run(List<Order> orders) throws Exception {
        try (ExecutorService exec = Executors.newVirtualThreadPerTaskExecutor()) {
            List<Future<Result>> futures = new ArrayList<>();
            for (Order o : orders) {
                futures.add(exec.submit(() -> processor.process(o)));
            }
            List<Result> results = new ArrayList<>();
            for (Future<Result> f : futures) {
                results.add(f.get());
            }
            return results;
        }     // close() waits for the tasks: shutdown() + awaitTermination()
    }
}

