package com.example.orders.app;

import com.example.orders.model.Order;
import com.example.orders.work.OrderProcessor;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

/** Shows the three-step shutdown: stop intake, wait politely, then interrupt. */
public class ShutdownDemo {
    public static void main(String[] args) throws InterruptedException {
        OrderProcessor processor = new OrderProcessor(50);
        AtomicInteger done = new AtomicInteger();
        AtomicInteger interrupted = new AtomicInteger();

        ExecutorService pool = Executors.newFixedThreadPool(4);
        for (int i = 1; i <= 40; i++) {
            Order o = new Order(i, "cust" + i, 1000);
            pool.submit(() -> {
                try {
                    processor.process(o);
                    done.incrementAndGet();
                } catch (IllegalStateException e) {
                    interrupted.incrementAndGet();
                }
            });
        }

        Thread.sleep(130);                       // let some work happen, then decide to stop
        pool.shutdown();                         // 1. no new tasks; queued ones still run
        boolean clean = pool.awaitTermination(60, TimeUnit.MILLISECONDS);   // 2. wait politely
        List<Runnable> neverStarted = List.of();
        if (!clean) {
            neverStarted = pool.shutdownNow();   // 3. drain the queue and interrupt workers
            pool.awaitTermination(1, TimeUnit.SECONDS);
        }
        System.out.println("clean shutdown : " + clean);
        System.out.println("completed      : " + done.get());
        System.out.println("interrupted    : " + interrupted.get());
        System.out.println("never started  : " + neverStarted.size());
        int total = done.get() + interrupted.get() + neverStarted.size();
        System.out.println("accounted for  : " + total);
    }
}

package com.example.orders.app;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.LongAdder;

/** Why shared counters need care: 4 threads x 250,000 increments should give 1,000,000. */
public class RaceDemo {
    static int plain;
    static volatile int volatileCounter;
    static final AtomicInteger atomic = new AtomicInteger();
    static final LongAdder adder = new LongAdder();

    public static void main(String[] args) throws InterruptedException {
        Thread[] threads = new Thread[4];
        for (int t = 0; t < threads.length; t++) {
            threads[t] = new Thread(() -> {
                for (int i = 0; i < 250_000; i++) {
                    plain++;                   // read, add, write: three steps, not atomic
                    volatileCounter++;         // visible, but still three steps
                    atomic.incrementAndGet();  // one atomic hardware operation
                    adder.increment();         // striped cells, merged on sum()
                }
            });
            threads[t].start();
        }
        for (Thread t : threads) {
            t.join();
        }
        System.out.println("plain int       : " + plain);
        System.out.println("volatile int    : " + volatileCounter);
        System.out.println("AtomicInteger   : " + atomic.get());
        System.out.println("LongAdder       : " + adder.sum());
    }
}

