package com.example.kv.store;

/** An immutable stored value. expiresAtMillis == 0 means "never expires". */
public record Entry(String value, long expiresAtMillis) {
    public boolean expired(long nowMillis) {
        return expiresAtMillis != 0 && nowMillis >= expiresAtMillis;
    }

    public static Entry of(String value, long ttlMillis, long nowMillis) {
        return new Entry(value, ttlMillis <= 0 ? 0 : nowMillis + ttlMillis);
    }
}

package com.example.kv.store;

import java.util.List;
import java.util.Optional;

public interface KeyValueStore {
    /** Store a value that never expires. */
    default void put(String key, String value) {
        put(key, value, 0);
    }

    /** Store a value that expires ttlMillis from now (ttlMillis <= 0 means never). */
    void put(String key, String value, long ttlMillis);

    Optional<String> get(String key);

    /** Returns true if a live entry existed. */
    boolean delete(String key);

    /** Atomically add one to a numeric value (a missing key counts as 0); returns the result. */
    long incr(String key);

    /** Number of live (not expired) entries. */
    int size();

    List<String> keys();

    /** Physically remove expired entries; returns how many were removed. */
    int purgeExpired();
}

package com.example.kv.store;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.LongSupplier;

/** Version 1: a plain HashMap guarded by a read-write lock. Many readers OR one writer. */
public class LockedStore implements KeyValueStore {
    private final Map<String, Entry> map = new HashMap<>();
    private final ReadWriteLock lock = new ReentrantReadWriteLock();
    private final LongSupplier clock;

    public LockedStore(LongSupplier clock) {
        this.clock = clock;
    }

    @Override
    public void put(String key, String value, long ttlMillis) {
        lock.writeLock().lock();
        try {
            map.put(key, Entry.of(value, ttlMillis, clock.getAsLong()));
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public Optional<String> get(String key) {
        lock.readLock().lock();
        try {
            Entry e = map.get(key);
            // Expired entries are only hidden here; removing needs the write lock (see purge).
            return e == null || e.expired(clock.getAsLong())
                    ? Optional.empty() : Optional.of(e.value());
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public boolean delete(String key) {
        lock.writeLock().lock();
        try {
            Entry e = map.remove(key);
            return e != null && !e.expired(clock.getAsLong());
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public long incr(String key) {
        lock.writeLock().lock();
        try {
            long now = clock.getAsLong();
            Entry old = map.get(key);
            boolean live = old != null && !old.expired(now);
            long next = (live ? Long.parseLong(old.value()) : 0) + 1;
            map.put(key, new Entry(Long.toString(next), live ? old.expiresAtMillis() : 0));
            return next;
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public int size() {
        lock.readLock().lock();
        try {
            long now = clock.getAsLong();
            return (int) map.values().stream().filter(e -> !e.expired(now)).count();
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<String> keys() {
        lock.readLock().lock();
        try {
            long now = clock.getAsLong();
            List<String> keys = new ArrayList<>();
            map.forEach((k, e) -> {
                if (!e.expired(now)) {
                    keys.add(k);
                }
            });
            keys.sort(null);
            return keys;
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public int purgeExpired() {
        lock.writeLock().lock();
        try {
            int before = map.size();
            long now = clock.getAsLong();
            map.values().removeIf(e -> e.expired(now));
            return before - map.size();
        } finally {
            lock.writeLock().unlock();
        }
    }
}

package com.example.kv.store;

import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.LongSupplier;

/** Version 2: no explicit locks; ConcurrentHashMap makes each single-key operation atomic. */
public class ConcurrentStore implements KeyValueStore {
    private final ConcurrentHashMap<String, Entry> map = new ConcurrentHashMap<>();
    private final LongSupplier clock;

    public ConcurrentStore(LongSupplier clock) {
        this.clock = clock;
    }

    @Override
    public void put(String key, String value, long ttlMillis) {
        map.put(key, Entry.of(value, ttlMillis, clock.getAsLong()));
    }

    @Override
    public Optional<String> get(String key) {
        Entry e = map.get(key);
        if (e == null) {
            return Optional.empty();
        }
        if (e.expired(clock.getAsLong())) {
            map.remove(key, e);          // only if still the same entry: a fresh put survives
            return Optional.empty();
        }
        return Optional.of(e.value());
    }

    @Override
    public boolean delete(String key) {
        Entry e = map.remove(key);
        return e != null && !e.expired(clock.getAsLong());
    }

    @Override
    public long incr(String key) {
        long now = clock.getAsLong();
        long[] result = new long[1];
        map.compute(key, (k, old) -> {           // runs atomically for this key
            boolean live = old != null && !old.expired(now);
            result[0] = (live ? Long.parseLong(old.value()) : 0) + 1;
            return new Entry(Long.toString(result[0]), live ? old.expiresAtMillis() : 0);
        });
        return result[0];
    }

    @Override
    public int size() {
        long now = clock.getAsLong();
        return (int) map.values().stream().filter(e -> !e.expired(now)).count();
    }

    @Override
    public List<String> keys() {
        long now = clock.getAsLong();
        return map.entrySet().stream().filter(e -> !e.getValue().expired(now))
                .map(Map.Entry::getKey).sorted().toList();
    }

    @Override
    public int purgeExpired() {
        long now = clock.getAsLong();
        int removed = 0;
        for (Map.Entry<String, Entry> e : map.entrySet()) {
            if (e.getValue().expired(now) && map.remove(e.getKey(), e.getValue())) {
                removed++;
            }
        }
        return removed;
    }
}

package com.example.kv.store;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.function.LongSupplier;

/**
 * Version 3: a bounded cache. LinkedHashMap in access order moves every entry we read to the
 * "newest" end, so the eldest entry is the least recently used. Because even get() changes the
 * order, reads are writes: a read-write lock would be wrong here, so we use plain synchronized.
 */
public class LruStore implements KeyValueStore {
    private final LongSupplier clock;
    private final int capacity;
    private long evictions;
    private final Map<String, Entry> map;

    public LruStore(int capacity, LongSupplier clock) {
        this.capacity = capacity;
        this.clock = clock;
        this.map = new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, Entry> eldest) {
                boolean evict = size() > LruStore.this.capacity;
                if (evict) {
                    evictions++;
                }
                return evict;
            }
        };
    }

    public synchronized long evictions() {
        return evictions;
    }

    @Override
    public synchronized void put(String key, String value, long ttlMillis) {
        map.put(key, Entry.of(value, ttlMillis, clock.getAsLong()));
    }

    @Override
    public synchronized Optional<String> get(String key) {
        Entry e = map.get(key);                // this call also marks the key as recently used
        if (e == null) {
            return Optional.empty();
        }
        if (e.expired(clock.getAsLong())) {
            map.remove(key);
            return Optional.empty();
        }
        return Optional.of(e.value());
    }

    @Override
    public synchronized boolean delete(String key) {
        Entry e = map.remove(key);
        return e != null && !e.expired(clock.getAsLong());
    }

    @Override
    public synchronized long incr(String key) {
        long now = clock.getAsLong();
        Entry old = map.get(key);
        boolean live = old != null && !old.expired(now);
        long next = (live ? Long.parseLong(old.value()) : 0) + 1;
        map.put(key, new Entry(Long.toString(next), live ? old.expiresAtMillis() : 0));
        return next;
    }

    @Override
    public synchronized int size() {
        long now = clock.getAsLong();
        return (int) map.values().stream().filter(e -> !e.expired(now)).count();
    }

    @Override
    public synchronized List<String> keys() {
        long now = clock.getAsLong();
        List<String> keys = new ArrayList<>();
        map.forEach((k, e) -> {
            if (!e.expired(now)) {
                keys.add(k);
            }
        });
        keys.sort(null);
        return keys;
    }

    @Override
    public synchronized int purgeExpired() {
        int before = map.size();
        long now = clock.getAsLong();
        map.values().removeIf(e -> e.expired(now));
        return before - map.size();
    }
}

package com.example.kv.store;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

/** Background sweeper: calls purgeExpired() on a fixed delay until closed. */
public class ExpiryCleaner implements AutoCloseable {
    private final ScheduledExecutorService scheduler;
    private final AtomicLong totalRemoved = new AtomicLong();

    public ExpiryCleaner(KeyValueStore store, long periodMillis) {
        this.scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r, "kv-expiry-cleaner");
            t.setDaemon(true);                     // never keeps the JVM alive by itself
            return t;
        });
        scheduler.scheduleWithFixedDelay(() -> {
            try {
                totalRemoved.addAndGet(store.purgeExpired());
            } catch (RuntimeException e) {        // an uncaught exception would cancel the schedule
                System.err.println("cleaner error: " + e);
            }
        }, periodMillis, periodMillis, TimeUnit.MILLISECONDS);
    }

    public long totalRemoved() {
        return totalRemoved.get();
    }

    @Override
    public void close() throws InterruptedException {
        scheduler.shutdown();
        scheduler.awaitTermination(1, TimeUnit.SECONDS);
    }
}

package com.example.kv.shell;

import com.example.kv.store.KeyValueStore;
import java.util.Locale;
import java.util.Optional;

/** Parses one command line and returns the reply text. Redis-flavoured on purpose. */
public class Shell {
    private final KeyValueStore store;

    public Shell(KeyValueStore store) {
        this.store = store;
    }

    public String execute(String line) {
        String[] w = line.trim().split("\\s+");
        if (w.length == 0 || w[0].isEmpty()) {
            return "";
        }
        try {
            return switch (w[0].toUpperCase(Locale.ROOT)) {
                case "SET" -> set(w);
                case "GET" -> {
                    need(w, 2, "GET key");
                    Optional<String> v = store.get(w[1]);
                    yield v.map(s -> "\"" + s + "\"").orElse("(nil)");
                }
                case "DEL" -> {
                    need(w, 2, "DEL key");
                    yield "(integer) " + (store.delete(w[1]) ? 1 : 0);
                }
                case "INCR" -> {
                    need(w, 2, "INCR key");
                    yield "(integer) " + store.incr(w[1]);
                }
                case "SIZE" -> "(integer) " + store.size();
                case "KEYS" -> store.keys().isEmpty() ? "(empty)" : String.join(" ", store.keys());
                case "PURGE" -> "(integer) " + store.purgeExpired();
                case "SLEEP" -> {                     // demo helper: let real time pass
                    need(w, 2, "SLEEP millis");
                    Thread.sleep(Long.parseLong(w[1]));
                    yield "OK";
                }
                default -> "ERR unknown command '" + w[0] + "'";
            };
        } catch (IllegalArgumentException e) {
            return "ERR " + e.getMessage();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return "ERR interrupted";
        }
    }

    private String set(String[] w) {
        if (w.length != 3 && w.length != 4) {
            throw new IllegalArgumentException("usage: SET key value [ttlMillis]");
        }
        long ttl = w.length == 4 ? Long.parseLong(w[3]) : 0;
        store.put(w[1], w[2], ttl);
        return "OK";
    }

    private static void need(String[] w, int count, String usage) {
        if (w.length != count) {
            throw new IllegalArgumentException("usage: " + usage);
        }
    }
}

package com.example.kv.shell;

import com.example.kv.store.ConcurrentStore;
import com.example.kv.store.ExpiryCleaner;
import com.example.kv.store.KeyValueStore;
import com.example.kv.store.LockedStore;
import com.example.kv.store.LruStore;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        String kind = args.length > 0 ? args[0] : "concurrent";
        KeyValueStore store = switch (kind) {
            case "locked" -> new LockedStore(System::currentTimeMillis);
            case "lru" -> new LruStore(3, System::currentTimeMillis);
            default -> new ConcurrentStore(System::currentTimeMillis);
        };
        System.out.println("store: " + store.getClass().getSimpleName());
        Shell shell = new Shell(store);
        try (ExpiryCleaner cleaner = new ExpiryCleaner(store, 50);
             Scanner in = new Scanner(System.in)) {
            while (in.hasNextLine()) {
                String line = in.nextLine();
                if (line.isBlank()) {
                    continue;
                }
                if (line.trim().equalsIgnoreCase("QUIT")) {
                    break;
                }
                System.out.println("> " + line);
                System.out.println(shell.execute(line));
            }
            System.out.println("cleaner removed " + cleaner.totalRemoved() + " expired entries");
        }
    }
}

package com.example.kv;

import static com.example.kv.MiniTest.assertEquals;
import static com.example.kv.MiniTest.assertThrows;
import static com.example.kv.MiniTest.assertTrue;

import com.example.kv.shell.Shell;
import com.example.kv.store.ConcurrentStore;
import com.example.kv.store.ExpiryCleaner;
import com.example.kv.store.KeyValueStore;
import com.example.kv.store.LockedStore;
import com.example.kv.store.LruStore;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Function;
import java.util.function.LongSupplier;

public class KvTests {
    /** A clock we control: tests move time forward by hand instead of sleeping. */
    static final class ManualTime implements LongSupplier {
        final AtomicLong now = new AtomicLong(1_000);

        @Override
        public long getAsLong() {
            return now.get();
        }

        void advance(long millis) {
            now.addAndGet(millis);
        }
    }

    public static void main(String[] args) {
        MiniTest t = new MiniTest();

        // The same contract tests run against every implementation.
        List<Function<LongSupplier, KeyValueStore>> factories = List.of(
                LockedStore::new, ConcurrentStore::new, clock -> new LruStore(100, clock));
        for (var factory : factories) {
            String n = factory.apply(() -> 0).getClass().getSimpleName();

            t.test(n + ": put, get, overwrite, delete", () -> {
                KeyValueStore s = factory.apply(new ManualTime());
                s.put("k", "v1");
                s.put("k", "v2");
                assertEquals(Optional.of("v2"), s.get("k"));
                assertTrue(s.delete("k"), "delete should report true");
                assertTrue(!s.delete("k"), "second delete should report false");
                assertEquals(Optional.empty(), s.get("k"));
            });
            t.test(n + ": entries expire after their ttl", () -> {
                ManualTime time = new ManualTime();
                KeyValueStore s = factory.apply(time);
                s.put("short", "x", 100);
                s.put("forever", "y");
                time.advance(99);
                assertEquals(Optional.of("x"), s.get("short"));
                time.advance(1);                                  // exactly at expiry: gone
                assertEquals(Optional.empty(), s.get("short"));
                assertEquals(1, s.size());
                assertEquals(List.of("forever"), s.keys());
            });
            t.test(n + ": purgeExpired removes only expired entries", () -> {
                ManualTime time = new ManualTime();
                KeyValueStore s = factory.apply(time);
                s.put("a", "1", 10);
                s.put("b", "2", 10);
                s.put("c", "3", 1000);
                time.advance(50);
                assertEquals(2, s.purgeExpired());
                assertEquals(0, s.purgeExpired());
                assertEquals(List.of("c"), s.keys());
            });
            t.test(n + ": incr is atomic across 4 threads", () -> {
                KeyValueStore s = factory.apply(new ManualTime());
                Thread[] ts = new Thread[4];
                for (int i = 0; i < ts.length; i++) {
                    ts[i] = new Thread(() -> {
                        for (int j = 0; j < 10_000; j++) {
                            s.incr("counter");
                        }
                    });
                    ts[i].start();
                }
                for (Thread th : ts) {
                    th.join();
                }
                assertEquals(Optional.of("40000"), s.get("counter"));
            });
        }

        t.test("LRU evicts the least recently used entry", () -> {
            LruStore s = new LruStore(3, new ManualTime());
            s.put("a", "1");
            s.put("b", "2");
            s.put("c", "3");
            s.get("a");                       // a is now the newest; b is the eldest
            s.put("d", "4");
            assertEquals(List.of("a", "c", "d"), s.keys());
            assertEquals(1L, s.evictions());
        });
        t.test("cleaner thread removes expired entries on its own", () -> {
            KeyValueStore s = new LockedStore(System::currentTimeMillis);
            try (ExpiryCleaner cleaner = new ExpiryCleaner(s, 10)) {
                s.put("x", "1", 20);
                Thread.sleep(150);
                assertEquals(1L, cleaner.totalRemoved());
            }
        });
        t.test("shell parses commands and reports errors", () -> {
            Shell sh = new Shell(new ConcurrentStore(new ManualTime()));
            assertEquals("OK", sh.execute("set a 1"));
            assertEquals("\"1\"", sh.execute("GET a"));
            assertEquals("(nil)", sh.execute("GET zzz"));
            assertEquals("ERR usage: SET key value [ttlMillis]", sh.execute("SET a"));
            assertEquals("ERR unknown command 'NOPE'", sh.execute("NOPE"));
            assertTrue(sh.execute("SET a 1 abc").startsWith("ERR"), "bad ttl must be an error");
        });
        t.test("incr on a non-number value fails clearly", () -> {
            KeyValueStore s = new ConcurrentStore(new ManualTime());
            s.put("name", "asha");
            assertThrows(NumberFormatException.class, () -> s.incr("name"));
        });

        System.exit(t.runAll() == 0 ? 0 : 1);
    }
}
